import json,sys
from api import dispatch

def main():
    try:
        result=dispatch(json.load(sys.stdin))
    except (ValueError,KeyError) as error:
        print(str(error),file=sys.stderr)
        return 2
    print(json.dumps(result,ensure_ascii=False))
    return 0

